struct Owners{contextual:Option<FontContextLayoutCursor>,contexts:PagedList<FontContextLayoutCursor,{usize::MAX}>,plan:FontLookupPlanCursor,lookups:Option<PagedList<FontLookup,{usize::MAX}>>,current:Vec<FontMappedScalar>,next:Vec<FontMappedScalar>,buffers:PagedList<Vec<FontMappedScalar>,{usize::MAX}>,ids:Vec<u16>,positions:Vec<usize>,classes:Vec<u16>,retained_ids:PagedList<Vec<u16>,{usize::MAX}>,retained_positions:PagedList<Vec<usize>,{usize::MAX}>,ligature:Option<FontLigatureCursor>,substitution:Option<FontSubstitutionCursor>,ligatures:PagedList<FontLigatureCursor,{usize::MAX}>,substitutions:PagedList<FontSubstitutionCursor,{usize::MAX}>,output:Option<FontClusterMapping>,failure:Option<&'static str>}
pub struct FontClusterLayoutCursor{owners:Owners,face:FontFace,mapping_face:usize,limits:FontOutlineLimits,phase:u8,cluster_scan:usize,cluster_source:usize,lookup_at:usize,at:usize,eligible_at:usize,copy_until:usize,class_probe:Option<FontGlyphClassCursor>,replacement:[u16;64],replacement_count:Option<usize>,replacement_at:usize,consumed:usize,work:u64,cancelled:bool,source_pointer:Option<usize>}
impl RetireOwned for FontClusterLayoutCursor{fn retirement(self)->Box<dyn RetirementCursor>{self.owners.retirement()}fn retirement_birth_bytes(&self)->Option<usize>{self.owners.retirement_birth_bytes()}fn controlled_retirement_supported()->bool{true}}
impl FontClusterLayoutCursor{
 pub fn new(face:FontFace,mapping:FontClusterMapping,limits:FontOutlineLimits)->Self{let invalid=mapping.glyphs.len()>limits.max_glyphs||!(1..=1000000000).contains(&limits.max_work);Self{owners:Owners{contextual:None,contexts:PagedList::new(),plan:FontLookupPlanCursor::new(face,true,*b"latn",&[*b"ccmp",*b"rlig",*b"liga",*b"clig",*b"calt"],limits.max_work),lookups:None,current:mapping.glyphs,next:Vec::new(),buffers:PagedList::new(),ids:Vec::new(),positions:Vec::new(),classes:Vec::new(),retained_ids:PagedList::new(),retained_positions:PagedList::new(),ligature:None,substitution:None,ligatures:PagedList::new(),substitutions:PagedList::new(),output:None,failure:invalid.then(||"Invalid original font layout authority".into())},face,mapping_face:mapping.face,limits,phase:0,cluster_scan:0,cluster_source:0,lookup_at:0,at:0,eligible_at:0,copy_until:0,class_probe:None,replacement:[0;64],replacement_count:None,replacement_at:0,consumed:0,work:0,cancelled:false,source_pointer:None}}
 fn step(&mut self,bytes:&[u8],work:&mut semio_framework_2d_text_font::work::FontWorkLedger)->Result<(),&'static str>{if !work.can_step(){return Ok(());}self.face.validate_source(bytes)?;if bytes.len()!=self.face.byte_length||self.source_pointer.is_some_and(|pointer|pointer!=bytes.as_ptr()as usize){return Err("Original font layout source changed".into());}self.source_pointer=Some(bytes.as_ptr()as usize);match self.phase{
  0=>{if self.owners.plan.advance(bytes,1,work)?.done{self.owners.lookups=Some(self.owners.plan.take_result()?);self.phase=1;}},
  1=>{let lookups=self.owners.lookups.as_ref().unwrap();if self.lookup_at==lookups.len(){self.owners.output=Some(FontClusterMapping{face:self.mapping_face,glyphs:std::mem::take(&mut self.owners.current)});self.phase=8;return Ok(());}let lookup=*lookups.get(self.lookup_at).unwrap();if !matches!(lookup.kind,1|2|4|5|6)||!matches!(lookup.flags,0|8){return Err("Font contextual or filtered layout authority requires resolution".into());}if matches!(lookup.kind,5|6){self.owners.contextual=Some(FontContextLayoutCursor::new(self.face,lookup,FontClusterMapping{face:self.mapping_face,glyphs:std::mem::take(&mut self.owners.current)},self.limits));self.phase=12;return Ok(());}let count=self.owners.current.len();if !work.contiguous(&mut self.owners.ids,count)?{return Ok(());};self.phase=2;},
  2=>{let count=self.owners.current.len();if !work.contiguous(&mut self.owners.positions,count)?{return Ok(());};self.phase=3;},
  3=>{let count=self.owners.current.len();if !work.contiguous(&mut self.owners.classes,count)?{return Ok(());};self.phase=4;},
  4=>{let count=self.owners.current.len().saturating_mul(64).min(self.limits.max_glyphs);if !work.contiguous(&mut self.owners.next,count)?{return Ok(());};self.at=0;self.eligible_at=0;self.phase=5;},
  5=>{if self.at==self.owners.current.len(){self.at=0;self.phase=6;return Ok(());}if !work.vec_slot(&mut self.owners.classes)?{return Ok(());}if !work.vec_slot(&mut self.owners.ids)?{return Ok(());}if !work.vec_slot(&mut self.owners.positions)?{return Ok(());}if self.class_probe.is_none(){self.class_probe=Some(FontGlyphClassCursor::new(self.face,self.owners.current[self.at].glyph)?);return Ok(());}if self.class_probe.as_mut().unwrap().step(bytes,work)?{let value=self.class_probe.take().unwrap().result()?;work.vec_push(&mut self.owners.classes,value).map_err(|(error,_)|error)?;let lookup=*self.owners.lookups.as_ref().unwrap().get(self.lookup_at).unwrap();if !(lookup.flags&8!=0&&value==3){work.vec_push(&mut self.owners.ids,self.owners.current[self.at].glyph).map_err(|(error,_)|error)?;work.vec_push(&mut self.owners.positions,self.at).map_err(|(error,_)|error)?;}self.at+=1;}},
  6=>{if self.at==self.owners.current.len(){if !work.slot(&mut self.owners.buffers)?||!work.slot(&mut self.owners.retained_ids)?||!work.slot(&mut self.owners.retained_positions)?{return Ok(());}work.push(&mut self.owners.buffers,std::mem::replace(&mut self.owners.current,std::mem::take(&mut self.owners.next))).map_err(|_|"Font source archive reservation lost")?;work.push(&mut self.owners.retained_ids,std::mem::take(&mut self.owners.ids)).map_err(|_|"Font eligible archive reservation lost")?;work.push(&mut self.owners.retained_positions,std::mem::take(&mut self.owners.positions)).map_err(|_|"Font position archive reservation lost")?;self.phase=11;return Ok(());}if self.owners.positions.get(self.eligible_at)!=Some(&self.at){if !work.vec_slot(&mut self.owners.next)?{return Ok(());}if self.owners.next.len()==self.limits.max_glyphs{return Err("Font layout glyph limit exceeded".into());}work.vec_push(&mut self.owners.next,self.owners.current[self.at]).map_err(|(error,_)|error)?;self.at+=1;return Ok(());}let lookup=*self.owners.lookups.as_ref().unwrap().get(self.lookup_at).unwrap();if lookup.kind==4{self.owners.ligature=Some(FontLigatureCursor::new(self.face,lookup,&self.owners.ids,self.eligible_at,self.limits.max_work));}else{self.owners.substitution=Some(FontSubstitutionCursor::new(self.face,lookup,self.owners.current[self.at].glyph,self.limits.max_work));}self.phase=7;},
  7=>{if let Some(child)=self.owners.ligature.as_mut(){if !child.advance(bytes,&self.owners.ids,1,work)?.done{return Ok(());}if !work.slot(&mut self.owners.ligatures)?{return Ok(());}let result=child.result()?;self.replacement_count=result.map(|value|{self.replacement[0]=value.glyph;1});self.consumed=result.map_or(1,|value|value.consumed);work.push(&mut self.owners.ligatures,self.owners.ligature.take().unwrap()).map_err(|_|"Font ligature child reservation lost")?;}else{let child=self.owners.substitution.as_mut().unwrap();if !child.advance(bytes,1,work)?.done{return Ok(());}if !work.slot(&mut self.owners.substitutions)?{return Ok(());}let result=child.result()?;self.replacement_count=result.map(|value|{self.replacement=value.glyphs;value.count});self.consumed=1;work.push(&mut self.owners.substitutions,self.owners.substitution.take().unwrap()).map_err(|_|"Font substitute child reservation lost")?;}self.replacement_at=0;self.copy_until=self.owners.positions[self.eligible_at+self.consumed-1]+1;self.cluster_scan=self.at;self.cluster_source=self.owners.current[self.at].source_at;self.phase=13;},
  13=>{if self.cluster_scan==self.copy_until{self.phase=9;}else{self.cluster_source=self.cluster_source.min(self.owners.current[self.cluster_scan].source_at);self.cluster_scan+=1;}},
  9=>{if self.replacement_count.is_some_and(|count|self.replacement_at<count){if !work.vec_slot(&mut self.owners.next)?{return Ok(());}if self.owners.next.len()==self.limits.max_glyphs{return Err("Font layout glyph limit exceeded".into());}let mut record=self.owners.current[self.at];record.glyph=self.replacement[self.replacement_at];record.source_at=self.cluster_source;self.replacement_at+=1;work.vec_push(&mut self.owners.next,record).map_err(|(error,_)|error)?;return Ok(());}if self.replacement_count.is_none(){if !work.vec_slot(&mut self.owners.next)?{return Ok(());}if self.owners.next.len()==self.limits.max_glyphs{return Err("Font layout glyph limit exceeded".into());}work.vec_push(&mut self.owners.next,self.owners.current[self.at]).map_err(|(error,_)|error)?;}self.at+=1;self.eligible_at+=self.consumed;self.phase=10;},
  10=>{if self.at==self.copy_until{self.phase=6;return Ok(());}let lookup=*self.owners.lookups.as_ref().unwrap().get(self.lookup_at).unwrap();if self.owners.classes[self.at]==3&&lookup.flags&8!=0{if !work.vec_slot(&mut self.owners.next)?{return Ok(());}if self.owners.next.len()==self.limits.max_glyphs{return Err("Font layout glyph limit exceeded".into());}work.vec_push(&mut self.owners.next,self.owners.current[self.at]).map_err(|(error,_)|error)?;}self.at+=1;},
  11=>{if !work.slot(&mut self.owners.retained_ids)?{return Ok(());}work.push(&mut self.owners.retained_ids,std::mem::take(&mut self.owners.classes)).map_err(|_|"Font class archive reservation lost")?;self.lookup_at+=1;self.phase=1;},
  12=>{if !self.owners.contextual.as_mut().unwrap().advance(bytes,1,work)?.done{return Ok(());}if !work.slot(&mut self.owners.contexts)?{return Ok(());}self.owners.current=self.owners.contextual.as_mut().unwrap().take_result()?.glyphs;work.push(&mut self.owners.contexts,self.owners.contextual.take().unwrap()).map_err(|_|"Original contextual child reservation lost")?;self.lookup_at+=1;self.phase=1;},
  _=>return Err("Original font layout stage invalid".into()),
 }Ok(())}
 pub fn advance(&mut self,bytes:&[u8],grant:usize,work:&mut semio_framework_2d_text_font::work::FontWorkLedger)->Result<FontProgress,&'static str>{let entered=work.enter();let result=(||{if grant==0{return Err("Invalid original font layout grant".into());}if self.cancelled{return Err("Original font layout cancelled".into());}if let Some(error)=&self.owners.failure{return Err(error.clone());}for _ in 0..(if entered.is_some(){grant.min(work.remaining().maximum_items)}else{0}){if self.phase==8{break;}if self.work==self.limits.max_work{self.owners.failure=Some("Font layout work limit exceeded".into());return Err(self.owners.failure.as_ref().unwrap().clone());}if let Err(error)=self.step(bytes,work){self.owners.failure=Some(error.clone());return Err(error);}if work.blocked(){break;}self.work+=1;work.note_source(entered==Some(true));}Ok(FontProgress{phase:match self.phase{0=>"plan",1=>"lookup",2|3|4=>"admission",5=>"filter",6=>"glyph",7=>"match",9=>"emit",10=>"skipped",11=>"archive",12=>"contextual",13=>"sourceCluster",_=>"complete"},work:self.work,done:self.phase==8})})();if entered.is_some(){work.exit();}result}
 pub fn result(&self)->Result<&FontClusterMapping,&'static str>{if self.phase!=8||self.cancelled||self.owners.failure.is_some(){return Err("Original font layout incomplete".into());}self.owners.output.as_ref().ok_or_else(||"Original font layout output transferred".into())}
 pub fn take_result(&mut self)->Result<FontClusterMapping,&'static str>{self.result()?;Ok(self.owners.output.take().unwrap())}
 pub fn cancel(&mut self){self.cancelled=true;}
}
